mapper.select:
SELECT tag_id, name, created_at
FROM tags
WHERE name = #{name}

SELECT tag_id, name, created_at
FROM tags
WHERE tag_id = #{tagId}

mapper.insert:
INSERT INTO tags (
    name, created_at
