mapper.select:
SELECT pt.post_id as postId, t.tag_id as "tag.tagId", t.name as "tag.name", t.created_at as "tag.createdAt" FROM post_tags pt JOIN tags t ON pt.tag_id = t.tag_id WHERE pt.post_id IN
#{id}
ORDER BY pt.post_id, t.name
